import sys

def main():
    n = int(sys.stdin.readline().strip())
    if n <= 0:
        return

    lines = []
    for i in range(n):
        start_idx = ord('A') + i
        line = ''.join(chr(start_idx + j) for j in range(n - i))
        if i > 0:
            line = ' ' + line
        lines.append(line)

    for line in lines:
        sys.stdout.write(line + '\n')
    for line in reversed(lines[1:]):
        sys.stdout.write(line + '\n')

if __name__ == "__main__":
    main()
